import React from "react";
import { motion } from "framer-motion";
import { Instagram } from "lucide-react";

// WhatsApp SVG Icon Component
const WhatsAppIcon = ({ size = 26, color = "white" }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill={color} xmlns="http://www.w3.org/2000/svg">
    <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"/>
  </svg>
);

// Floating button animation variants
const buttonVariants = {
  initial: { scale: 0, opacity: 0 },
  animate: (i) => ({
    scale: 1,
    opacity: 1,
    transition: { delay: 2.5 + i * 0.15, type: "spring", stiffness: 260, damping: 20 }
  }),
  hover: {
    scale: 1.15,
    rotate: [0, -5, 5, 0],
    transition: { duration: 0.3 }
  },
  tap: { scale: 0.9 }
};

// Pulse ring animation
const pulseVariants = {
  animate: {
    scale: [1, 1.5, 1],
    opacity: [0.6, 0, 0.6],
    transition: { duration: 2.4, repeat: Infinity, ease: "easeOut" }
  }
};

export default function FloatingButtons() {
  const whatsappLinks = [
    { number: "919888919983", label: "Chat with us" },
    { number: "917355555649", label: "Call us" },
  ];

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col gap-3">
      {whatsappLinks.map((wa, i) => (
        <motion.a
          key={wa.number}
          href={`https://wa.me/${wa.number}?text=Hi!%20I'm%20interested%20in%20D%20SAJAWAT%20fabrics%20for%20wedding/event`}
          target="_blank"
          rel="noopener noreferrer"
          className="relative group"
          title={wa.label}
          custom={i}
          variants={buttonVariants}
          initial="initial"
          animate="animate"
          whileHover="hover"
          whileTap="tap"
        >
          {/* Animated pulse ring */}
          <motion.div
            className="absolute inset-0 rounded-full"
            style={{ background: "rgba(37, 211, 102, 0.6)", boxShadow: "0 0 0 0 rgba(37, 211, 102, 0.6)" }}
            variants={pulseVariants}
            animate="animate"
          />

          {/* Button */}
          <motion.div
            className="relative flex items-center justify-center rounded-full"
            style={{
              width: 56,
              height: 56,
              background: "linear-gradient(135deg, #25d366 0%, #128c7e 100%)",
              boxShadow: "0 8px 32px rgba(0, 0, 0, 0.2), 0 0 0 1px rgba(212, 175, 55, 0.3)"
            }}
            whileHover={{
              boxShadow: "0 16px 48px rgba(37, 211, 102, 0.4), 0 0 0 1px rgba(212, 175, 55, 0.5)"
            }}
          >
            <motion.div
              animate={{ scale: [1, 1.1, 1] }}
              transition={{ duration: 1.5, repeat: Infinity }}
            >
              <WhatsAppIcon size={30} />
            </motion.div>
          </motion.div>

          {/* Tooltip */}
          <motion.div
            className="absolute right-full mr-3 top-1/2 -translate-y-1/2 px-3 py-2 rounded-lg text-xs whitespace-nowrap pointer-events-none"
            style={{ background: "rgba(26, 8, 10, 0.95)", border: "1px solid rgba(212, 175, 55, 0.4)", color: "#f7e7ce" }}
            initial={{ opacity: 0, x: 10 }}
            whileHover={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.2 }}
          >
            {wa.label}
          </motion.div>
        </motion.a>
      ))}

      {/* Instagram Button */}
      <motion.a
        href="https://www.instagram.com/d_sajawat/"
        target="_blank"
        rel="noopener noreferrer"
        className="relative group"
        title="Follow us on Instagram"
        custom={whatsappLinks.length}
        variants={buttonVariants}
        initial="initial"
        animate="animate"
        whileHover="hover"
        whileTap="tap"
      >
        <motion.div
          className="relative flex items-center justify-center rounded-full"
          style={{
            width: 56,
            height: 56,
            background: "linear-gradient(135deg, #f09433 0%, #e6683c 25%, #dc2743 50%, #cc2366 75%, #bc1888 100%)",
            boxShadow: "0 8px 32px rgba(0, 0, 0, 0.2), 0 0 0 1px rgba(212, 175, 55, 0.3)"
          }}
          whileHover={{
            rotate: 10,
            boxShadow: "0 16px 48px rgba(220, 39, 67, 0.4), 0 0 0 1px rgba(212, 175, 55, 0.5)"
          }}
        >
          <Instagram size={24} color="white" />
        </motion.div>

        {/* Tooltip */}
        <motion.div
          className="absolute right-full mr-3 top-1/2 -translate-y-1/2 px-3 py-2 rounded-lg text-xs whitespace-nowrap pointer-events-none"
          style={{ background: "rgba(26, 8, 10, 0.95)", border: "1px solid rgba(212, 175, 55, 0.4)", color: "#f7e7ce" }}
          initial={{ opacity: 0, x: 10 }}
          whileHover={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.2 }}
        >
          @d_sajawat
        </motion.div>
      </motion.a>
    </div>
  );
}
